399:   protected void doNext(Context parentContext, final Registry registry, final int nextIndex, final Handler[] nextHandlers, Handler exhausted) {
400:     Context context;
401:     Handler handler;
402: 
403:     if (nextIndex >= nextHandlers.length) {
404:       context = parentContext;
405:       handler = exhausted;
406:     } else {
407:       handler = nextHandlers[nextIndex];
408:       context = createContext(registry, nextHandlers, nextIndex + 1, exhausted);
409:     }
410: 
411:     try {
412:       handler.handle(context);
413:     } catch (Exception e) {
414:       if (e instanceof HandlerException) {
415:         throw (HandlerException) e;
416:       } else {
417:         throw new HandlerException(context, e);
418:       }
419:     }
420:   }
