422:   private DefaultContext createContext(Registry registry, Handler[] nextHandlers, int nextIndex, Handler exhausted) {
423:     return new DefaultContext(directChannelAccess, request, response, bindAddress, registry, backgroundExecutorService, foregroundExecutorService, onCloseRegistry, nextHandlers, nextIndex, exhausted);
424:   }
